import uiautomation as auto
auto.SetGlobalSearchTimeout(2)
for hwnd in (462320,67948):
    print("HWND", hwnd)
    try:
        c=auto.ControlFromHandle(hwnd)
        print("ROOT", c.Name, c.ControlTypeName, c.ClassName)
        kids=c.GetChildren()
        print("CHILDREN", len(kids))
        for k in kids[:30]:
            try:
                print(" -", repr(k.Name), k.ControlTypeName, k.ClassName)
            except Exception as e:
                print(" - ERR",e)
    except Exception as e:
        print("ERR",repr(e))
